-- Tenant persona overrides (REGISTRY-010, CONTEXT_PACK §4.6 / §7 / §8.6 / §8.11). Generated by
-- `pnpm db:generate --name persona_overrides` from src/schema/persona-overrides.ts, then reviewed. Forward-only:
-- never edit once applied; add a new migration. Tools, the intrusiveness ceiling and the model map are not columns.
CREATE TABLE "persona_overrides" (
	"tenant_id" uuid NOT NULL,
	"persona" text NOT NULL,
	"effort" text,
	"max_turns" integer,
	"max_budget_usd" double precision,
	"lower_standard_tier" boolean,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "persona_overrides_pk" PRIMARY KEY("tenant_id","persona"),
	CONSTRAINT "persona_overrides_persona_check" CHECK ("persona_overrides"."persona" ~ '^[a-z][a-z0-9-]{0,63}$'),
	CONSTRAINT "persona_overrides_effort_check" CHECK ("persona_overrides"."effort" IS NULL OR "persona_overrides"."effort" IN ('low', 'medium', 'high', 'xhigh', 'max')),
	CONSTRAINT "persona_overrides_max_turns_check" CHECK ("persona_overrides"."max_turns" IS NULL OR "persona_overrides"."max_turns" BETWEEN 1 AND 10000),
	CONSTRAINT "persona_overrides_max_budget_check" CHECK ("persona_overrides"."max_budget_usd" IS NULL OR ("persona_overrides"."max_budget_usd" > 0 AND "persona_overrides"."max_budget_usd" <= 10000))
);
--> statement-breakpoint
ALTER TABLE "persona_overrides" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "persona_overrides_tenant_isolation" ON "persona_overrides" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);

--> statement-breakpoint
-- Hand-written below (Drizzle models neither FORCE ROW LEVEL SECURITY, grants nor triggers). Reviewed.
-- FORCE: the owner role is subject to the tenant policy too, so nothing reads across tenants.
ALTER TABLE "persona_overrides" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
-- The runtime role gets SELECT/INSERT/UPDATE only: no DELETE and no TRUNCATE, never PUBLIC. A reset is an update.
REVOKE ALL ON "persona_overrides" FROM PUBLIC;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "persona_overrides" FROM bw_app;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "persona_overrides" TO bw_app;--> statement-breakpoint
-- Keeps updated_at in step with every write (bw_set_updated_at: 0002_column_mixins).
CREATE TRIGGER persona_overrides_set_updated_at BEFORE UPDATE ON persona_overrides FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
